SELECT COUNT(*) AS total_reviews,
       SUM(CASE WHEN LOWER(text) LIKE '%smell%' OR LOWER(text) LIKE '%scent%' OR LOWER(text) LIKE '%fragrance%' OR LOWER(text) LIKE '%odor%' OR LOWER(text) LIKE '%perfume%' OR LOWER(text) LIKE '%aroma%' THEN 1 ELSE 0 END) AS scent_mentions
FROM reviews;

SELECT COUNT(*) AS review_count, AVG(rating) AS avg_rating
FROM reviews
WHERE parent_asin = 'B0BRJH1WL4';

SELECT AVG(rating) AS avg_rating
FROM reviews
WHERE parent_asin = 'B0BRJH1WL4';

SELECT AVG(rating) AS avg_rating, COUNT(*) AS review_count
FROM reviews
WHERE parent_asin = 'B0BRJH1WL4';
